  expect(html).not.toMatch(/AudioContext|webkitAudioContext|new Audio\(|\.mp3|\.wav|clipboard\.write/);
  expect(await page.locator('meta[name="viewport"]').getAttribute('content')).not.toMatch(/maximum-scale|user-scalable/);
  await context.close();
});

