  for (let i = deck.length - 1; i > 0; i--) {
    const possibilities = i + 1;
    const limit = Math.floor(GENERATOR_VALUES / possibilities) * possibilities;
    let draw: number;
    do {
      state = nextGeneratorState(state);
      draw = state - 1;
