    expect(c.view.celebrate).toBe(false);
    expect(c.view.best).toBe(20);
    expect(c.view.status).toBe('Loaded completed snapshot.');
    expect(saves).toHaveLength(1);
    expect(saves[0]?.best[4]).toBe(20);
  });
});

