  const sample = new Uint32Array(1);
  try { crypto.getRandomValues(sample); }
  catch { sample[0] = Math.floor(Math.random() * 4294967296); }
  let seed = ((sample[0] ?? 0) % MAX_SEED) + 1;
  if (seed === previousSeed) seed = seed === MAX_SEED ? 1 : seed + 1;
