import type { GameState } from '../state.ts';
import { isWon } from '../state.ts';
import { formatTime } from './formatTime.ts';
import './GameStatus.css';

export interface GameStatusProps {
  readonly game: GameState;
  readonly best: number | null;
  readonly paused: boolean;
  readonly celebrate: boolean;
}

export function GameStatus({ game, best, paused, celebrate }: GameStatusProps) {
  return <section className="game-status" aria-label="Game status">
    <div className="stats">
      <p>Moves: {game.moves}</p>
      <p>Pairs: {game.matched.length / 2}/{game.deck.length / 2}</p>
      <p>Time: {formatTime(game.elapsedMs)}</p>
      <p>Best: {best ?? 'none'}</p>
    </div>
    {paused && <p className="pause-note">Paused · Select Resume in Reproduce a game to continue.</p>}
    {isWon(game) && <div className={`win-banner${celebrate ? ' celebrate' : ''}`}>
      <h2>All pairs found!</h2>
      <p>{game.moves} moves · {formatTime(game.elapsedMs)}</p>
    </div>}
  </section>;
}
.game-status { display: grid; gap: 12px; }
.stats { display: flex; flex-wrap: wrap; gap: 8px 24px; font-variant-numeric: tabular-nums; }
.stats p { white-space: nowrap; }
.pause-note { color: var(--secondary); font-size: 14px; }
.win-banner { padding: 16px; border: 1px solid #8BEA7D; border-radius: 8px; background: var(--panel); }
.win-banner h2 { color: #8BEA7D; font-size: 20px; line-height: 24px; }
.win-banner p { margin-top: 4px; }
.celebrate { animation: completion-pulse 600ms ease-out 1; }
@keyframes completion-pulse { 50% { box-shadow: 0 0 16px #8BEA7D; } }
@media (prefers-reduced-motion: reduce) { .celebrate { animation: none; } }

